var POLISH_EU_CITIES = RAW_PLACES.map(
  ([name, admin1, country, lat, lon, tz, altNames]) => ({
    name,
    admin1,
    country,
    lat,
    lon,
    tz,
    ...altNames ? { altNames } : {}
  })
);
var NEAREST_MAJOR_POLISH_CITIES = POLISH_EU_CITIES.slice(0, 12);
function normalizePlaceQuery(value) {
  return value.trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ł/g, "l").replace(/ß/g, "ss");
}
function formatPlaceLabel(place) {
  if (place.admin1 && normalizePlaceQuery(place.admin1) !== normalizePlaceQuery(place.name)) {
    return `${place.name}, ${place.admin1}, ${place.country}`;
  }
  return `${place.name}, ${place.country}`;
}
function searchCities(query, limit = 8) {
  const safeLimit = Math.max(1, Math.min(20, Math.floor(limit) || 8));
  const normQ = normalizePlaceQuery(query);
  if (!normQ) return POLISH_EU_CITIES.slice(0, safeLimit);
  const exactMatches = [];
  const startsWith = [];
  const includes = [];
  for (const city of POLISH_EU_CITIES) {
    const candidates = [city.name, ...city.altNames ?? []].map(normalizePlaceQuery);
    const labelNorm = normalizePlaceQuery(formatPlaceLabel(city));
    if (candidates.some((c) => c === normQ) || labelNorm === normQ) {
      exactMatches.push(city);
    } else if (candidates.some((c) => c.startsWith(normQ))) {
      startsWith.push(city);
    } else if (candidates.some((c) => c.includes(normQ)) || normalizePlaceQuery(city.admin1).includes(normQ) || normalizePlaceQuery(city.country).includes(normQ) || labelNorm.includes(normQ)) {
      includes.push(city);
    }
  }
  return [...exactMatches, ...startsWith, ...includes].slice(0, safeLimit);
}
function findExactCity(query) {
  const normQ = normalizePlaceQuery(query);
  if (!normQ) return null;
  for (const city of POLISH_EU_CITIES) {
    const candidates = [
      city.name,
      `${city.name}, ${city.country}`,
      formatPlaceLabel(city),
      ...city.altNames ?? []
    ].map(normalizePlaceQuery);
    if (candidates.includes(normQ)) {
      return city;
    }
  }
  return null;
}
function resolveCityCoordinates(cityName, structured) {
  if (structured && typeof structured.name === "string" && typeof structured.lat === "number" && Number.isFinite(structured.lat) && typeof structured.lon === "number" && Number.isFinite(structured.lon) && typeof structured.tz === "string" && structured.tz.length > 0) {
    return {
      name: structured.name,
      admin1: structured.admin1 ?? "",
      country: structured.country ?? "Polska",
      lat: structured.lat,
      lon: structured.lon,
      tz: structured.tz
    };
  }
  const exact = findExactCity(cityName);
  if (exact) return exact;
  const matches = searchCities(cityName, 1);
  if (matches.length > 0 && cityName.trim().length > 0) {
    return matches[0];
  }
  return POLISH_EU_CITIES[0];
}

